import Consent from "./consent";
import Home from "./home";

function App() {
  return (
    <Router>
      <Routes>
        {/* Splash page shows first */}
        <Route path="/" element={<Consent />} />

        {/* Main website */}
        <Route path="/home" element={<Home />} />
      </Routes>
    </Router>
  );
}

export default App;
